    if ok[j] and substring s[j..i) is in the word set:
      ok[i] = true
      stop looking at this i
return ok[length of s]

result = [ empty list ]
for x in nums:
  for each existing subset s in result (snapshot before this round):
    add a copy of s with x appended to result
return result

sort intervals by start
result = [ first interval ]
for each interval cur in the rest:
  last = final interval in result
  if cur.start <= last.end:
    last.end = max(last.end, cur.end)
  else:
    append cur to result
return result

